checks.command:
node --input-type=module - <<'JS'
import { readFileSync, writeFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import { eventsToAgentSession } from '{scratch}/openhands-export.mjs';
const p='{package-root}/openhands/';
const f=JSON.parse(readFileSync(p+'samples/native/native.json','utf8'));
const text=eventsToAgentSession(f.events,f.sessionId);
assert.equal(typeof text,'string');
assert.deepEqual(text.trim().split('\n').map(JSON.parse),readFileSync(p+'samples/asr/session.jsonl','utf8').trim().split('\n').map(JSON.parse));
writeFileSync(p+'samples/asr/session.jsonl',text);
JS
